/**
 * Normalizes a path into a project-relative, forward-slash-separated string
 * suitable for matching against the `ignore` library.
 *
 * @param projectRoot The absolute path to the project root.
 * @param filePath The path to normalize. May be absolute or relative to the
 *   project root.
 * @param isDirectory Whether the path refers to a directory. When true, a
 *   trailing slash is appended so that directory-specific patterns (e.g.
 *   `dist/`) match; when false any trailing slash is stripped.
 * @returns The normalized relative path, or `null` when the input is invalid
 *   (empty/non-string) or resolves outside the project root.
 */
export function getNormalizedRelativePath(
  projectRoot: string,
  filePath: string,
  isDirectory: boolean,
): string | null {
  if (!filePath || typeof filePath !== 'string') {
    return null;
  }

  const absoluteFilePath = path.resolve(projectRoot, filePath);

  // Reject anything outside the project root: paths above the root, siblings
  // that merely share a name prefix, and Windows cross-drive absolute paths.
  if (!isWithinRoot(absoluteFilePath, projectRoot)) {
    return null;
  }

  const relativePath = path.relative(projectRoot, absoluteFilePath);

  // Even on Windows, the `ignore` library expects forward slashes.
  let normalizedPath = relativePath.replace(/\\/g, '/');

  // Align the trailing slash with whether this is a directory.
  if (isDirectory) {
    if (!normalizedPath.endsWith('/')) {
      normalizedPath += '/';
    }
  } else if (normalizedPath.endsWith('/')) {
    normalizedPath = normalizedPath.slice(0, -1);
  }

  // The path refers to the project root itself.
  if (normalizedPath === '' || normalizedPath === '/') {
    return isDirectory ? '/' : '';
  }

  // Strip any leading slash so patterns match relative paths.
  if (normalizedPath.startsWith('/')) {
    normalizedPath = normalizedPath.slice(1);
  }

  return normalizedPath;
}
